<section class="page-hero shell compact"><p class="kicker">Your Atelier</p><h1>Delivery addresses.</h1><p>Saved securely and used only for your orders.</p></section><section class="section section-tight shell account-grid"><?php include __DIR__.'/_nav.php'; ?><div class="account-main"><div class="panel-head"><h2>Saved addresses</h2><a class="btn dark" href="<?=e(url('/account/address/new'))?>">Add address</a></div><?php if(!$addresses):?><div class="empty-state"><h2>No saved address yet.</h2><p>Add your delivery address before checkout.</p></div><?php else:?><div class="address-grid"><?php foreach($addresses as $a):?><article class="address-card"><div class="panel-head"><span class="status-pill"><?=e($a['type'])?><?=!empty($a['is_default'])?' · default':''?></span><a href="<?=e(url('/account/address/'.$a['guid']))?>">Edit</a></div><h3><?=e($a['name'])?></h3><p><?=e($a['line1'])?><br><?php if($a['line2']):?><?=e($a['line2'])?><br><?php endif;?><?=e($a['city'])?>, <?=e($a['state'])?> <?=e($a['pincode'])?></p><small><?=e($a['phone'])?></small><form method="post" action="<?=e(url('/account/address/'.$a['guid'].'/delete'))?>" data-confirm="Remove this address?"><?=csrf_field()?><button class="text-danger" type="submit">Remove</button></form></article><?php endforeach;?></div><?php endif;?></div></section>
